// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title ServiceDelegationRegistry
 * @notice Manages delegation chains for gRPC service authentication
 * @dev Implements constrained delegation similar to Kerberos S4U2Proxy
 */
contract ServiceDelegationRegistry {

    enum Role { NONE, USER, SERVICE, ADMIN }

    struct DelegationTicket {
        address originalCaller;
        address delegatedService;
        address targetService;
        uint256 expiry;
        bytes32 sessionKey;
        bool constrained;
    }

    struct ServicePrincipal {
        Role role;
        bool allowedToDelegate;
        mapping(address => bool) trustedDelegators;
        mapping(address => bool) allowedTargets;
        uint256 registeredAt;
    }

    mapping(address => ServicePrincipal) public principals;
    mapping(bytes32 => DelegationTicket) public tickets;
    mapping(address => mapping(address => uint256)) public delegationNonces;

    address public kdc; // Key Distribution Center admin

    event TicketGranted(bytes32 indexed ticketId, address indexed from, address indexed to);
    event DelegationExecuted(bytes32 indexed ticketId, address target);

    modifier onlyKDC() {
        require(msg.sender == kdc, "Only KDC");
        _;
    }

    modifier onlyRole(Role _minRole) {
        require(uint8(principals[msg.sender].role) >= uint8(_minRole), "Insufficient role");
        _;
    }

    constructor() {
        kdc = msg.sender;
        principals[msg.sender].role = Role.ADMIN;
        principals[msg.sender].registeredAt = block.timestamp;
    }

    function registerService(address _service, Role _role, bool _canDelegate) external onlyKDC {
        require(_role != Role.NONE, "Invalid role");
        principals[_service].role = _role;
        principals[_service].allowedToDelegate = _canDelegate;
        principals[_service].registeredAt = block.timestamp;
    }

    function addTrustedDelegator(address _delegator) external onlyRole(Role.SERVICE) {
        principals[msg.sender].trustedDelegators[_delegator] = true;
    }

    function addAllowedTarget(address _service, address _target) external onlyKDC {
        principals[_service].allowedTargets[_target] = true;
    }

    function requestServiceTicket(
        address _targetService,
        uint256 _duration
    ) external onlyRole(Role.USER) returns (bytes32) {
        require(_duration <= 3600, "Max 1 hour");
        require(principals[_targetService].role == Role.SERVICE, "Target not a service");

        bytes32 sessionKey = keccak256(abi.encodePacked(
            msg.sender, _targetService, block.timestamp, block.prevrandao
        ));

        bytes32 ticketId = keccak256(abi.encodePacked(
            msg.sender, _targetService, delegationNonces[msg.sender][_targetService]++
        ));

        tickets[ticketId] = DelegationTicket({
            originalCaller: msg.sender,
            delegatedService: address(0),
            targetService: _targetService,
            expiry: block.timestamp + _duration,
            sessionKey: sessionKey,
            constrained: true
        });

        emit TicketGranted(ticketId, msg.sender, _targetService);
        return ticketId;
    }

    /**
     * @notice S4U2Proxy - Service delegates on behalf of user to another service
     * @dev The constrained delegation check validates the chain
     */
    function delegateTicket(
        bytes32 _originalTicketId,
        address _newTarget
    ) external onlyRole(Role.SERVICE) returns (bytes32) {
        DelegationTicket storage original = tickets[_originalTicketId];

        require(original.expiry > block.timestamp, "Ticket expired");
        require(original.targetService == msg.sender, "Not your ticket");
        require(principals[msg.sender].allowedToDelegate, "Delegation not allowed");

        // Constrained delegation check: verify the intermediate service
        // is allowed to delegate to the new target
        _validateDelegationConstraints(msg.sender, _newTarget, original.constrained);

        bytes32 newSessionKey = keccak256(abi.encodePacked(
            original.sessionKey, _newTarget, block.timestamp
        ));

        bytes32 newTicketId = keccak256(abi.encodePacked(
            original.originalCaller, _newTarget, 
            delegationNonces[original.originalCaller][_newTarget]++
        ));

        tickets[newTicketId] = DelegationTicket({
            originalCaller: original.originalCaller,
            delegatedService: msg.sender,
            targetService: _newTarget,
            expiry: original.expiry,
            sessionKey: newSessionKey,
            constrained: original.constrained
        });

        emit DelegationExecuted(newTicketId, _newTarget);
        return newTicketId;
    }

    function _validateDelegationConstraints(
        address _service,
        address _target,
        bool _isConstrained
    ) internal view {
        if (_isConstrained) {
            // Check if target trusts the delegating service
            bool targetTrustsDelegator = principals[_target].trustedDelegators[_service];
            // Check if service is allowed to reach this target
            bool serviceAllowedTarget = principals[_service].allowedTargets[_target];

            // Both conditions must hold: mutual agreement required
            // Target must trust the delegator AND KDC must have approved the path
            require(targetTrustsDelegator && serviceAllowedTarget, "Delegation constraint violated");
        }
    }

    function executeOnBehalf(
        bytes32 _ticketId,
        bytes calldata _payload
    ) external onlyRole(Role.SERVICE) returns (bool) {
        DelegationTicket storage ticket = tickets[_ticketId];

        require(ticket.expiry > block.timestamp, "Ticket expired");
        require(ticket.targetService == msg.sender, "Wrong target");

        // Verify delegation chain integrity
        if (ticket.delegatedService != address(0)) {
            require(
                principals[ticket.delegatedService].allowedToDelegate,
                "Delegator lost privileges"
            );
        }

        // Execute the gRPC call context with original caller's identity
        // (simplified - in practice this would invoke the service logic)
        return _processServiceCall(ticket.originalCaller, _payload);
    }

    function _processServiceCall(
        address _caller,
        bytes calldata _payload
    ) internal pure returns (bool) {
        // Placeholder for actual service logic
        return _payload.length > 0 && _caller != address(0);
    }

    function revokeTicket(bytes32 _ticketId) external {
        DelegationTicket storage ticket = tickets[_ticketId];
        require(
            msg.sender == ticket.originalCaller || 
            msg.sender == kdc,
            "Not authorized to revoke"
        );
        delete tickets[_ticketId];
    }
}
